return [
  {
    json: {
      from: 'Client Test <client@example.com>',
      subject: 'Ou est ma commande ?',
      text: 'Bonjour, je voudrais savoir ou se trouve ma commande. Merci',
      id: 'manual-test-message',
      threadId: ''
    }
  }
];

const idx = typeof $itemIndex === 'number' ? $itemIndex : 0;

let triggerItem = {};
try {
  const triggerItems = $items('Gmail Trigger - New Client Email');
  triggerItem = Array.isArray(triggerItems) && triggerItems[idx] && triggerItems[idx].json ? triggerItems[idx].json : {};
} catch {
  triggerItem = {};
}

const inputEnvelope = $input.first().json || {};
const hasTrigger = Object.keys(triggerItem).length > 0;
const source = hasTrigger ? triggerItem : inputEnvelope;
const threadEnvelope = Array.isArray(inputEnvelope.messages) ? inputEnvelope : {};

const unique = (values) => [...new Set(values.map((value) => String(value || '').trim()).filter(Boolean))];

function normalizeText(value) {
  return String(value || '')
    .replace(/\r/g, '\n')
    .replace(/[ \t]{2,}/g, ' ')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function extractEmail(value) {
  const raw = String(value || '').trim();
  if (!raw) return '';
  const angle = raw.match(/<([^>]+)>/);
  if (angle && angle[1]) return angle[1].trim().toLowerCase();
  const direct = raw.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i);
  return direct ? direct[0].toLowerCase() : '';
}

function extractEmails(value) {
  return unique((String(value || '').match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/ig) || []).map((email) => email.toLowerCase()));
}

function extractEmailFromAny(value) {
  if (!value) return '';
  if (typeof value === 'string') return extractEmail(value);
  if (Array.isArray(value)) {
    for (const item of value) {
      const found = extractEmailFromAny(item);
      if (found) return found;
    }
    return '';
  }
  if (typeof value === 'object') {
    return extractEmail(value.address) || extractEmail(value.email) || extractEmail(value.text) || extractEmail(value.html) || extractEmail(value.value) || '';
  }
  return extractEmail(String(value));
}

function extractNameFromAny(value) {
  if (!value) return '';
  if (typeof value === 'string') {
    const raw = String(value).trim();
    const angle = raw.match(/^([^<]+)</);
    return angle && angle[1] ? angle[1].replace(/["']/g, '').trim() : '';
  }
  if (Array.isArray(value)) {
    for (const item of value) {
      const found = extractNameFromAny(item);
      if (found) return found;
    }
    return '';
  }
  if (typeof value === 'object') return String(value.name || value.displayName || '').trim();
  return '';
}

function decodeBase64Url(input) {
  const raw = String(input || '').trim();
  if (!raw) return '';
  const normalized = raw.replace(/-/g, '+').replace(/_/g, '/');
  const padded = normalized + '='.repeat((4 - (normalized.length % 4)) % 4);
  try {
    return Buffer.from(padded, 'base64').toString('utf8');
  } catch {
    return '';
  }
}

function decodeQuotedPrintable(input) {
  const src = String(input || '');
  if (!src || !/=(?:\r?\n|[A-F0-9]{2})/i.test(src)) return src;
  const cleaned = src.replace(/=(\r?\n)/g, '');
  const bytes = [];
  for (let i = 0; i < cleaned.length; i += 1) {
    const ch = cleaned[i];
    if (ch === '=' && /^[A-F0-9]{2}$/i.test(cleaned.slice(i + 1, i + 3))) {
      bytes.push(parseInt(cleaned.slice(i + 1, i + 3), 16));
      i += 2;
    } else {
      bytes.push(...Buffer.from(ch, 'utf8'));
    }
  }
  try {
    return Buffer.from(bytes).toString('utf8');
  } catch {
    return cleaned;
  }
}

function decodeHtml(input) {
  return String(input || '')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;|&apos;/gi, "'")
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/p>/gi, '\n')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<[^>]+>/g, ' ');
}

function buildHeaderMap(message) {
  const values = [];
  if (Array.isArray(message?.headers)) {
    values.push(...message.headers);
  } else if (message?.headers && typeof message.headers === 'object') {
    for (const [name, value] of Object.entries(message.headers)) {
      if (Array.isArray(value)) value.forEach((item) => values.push({ name, value: String(item || '') }));
      else values.push({ name, value: String(value || '') });
    }
  }
  if (Array.isArray(message?.payload?.headers)) values.push(...message.payload.headers);
  const map = {};
  for (const header of values) {
    const key = String(header?.name || '').toLowerCase();
    if (!key) continue;
    map[key] = map[key] || [];
    map[key].push(String(header?.value || ''));
  }
  return map;
}

const getHeader = (map, name) => (map[String(name || '').toLowerCase()] || [])[0] || '';

function payloadToText(message) {
  const plain = [];
  const html = [];
  const visit = (part) => {
    if (!part) return;
    const mime = String(part.mimeType || '').toLowerCase();
    const data = part.body?.data ? decodeBase64Url(part.body.data) : '';
    if (data && mime.includes('text/plain')) plain.push(data);
    else if (data && mime.includes('text/html')) html.push(decodeHtml(data));
    if (Array.isArray(part.parts)) part.parts.forEach(visit);
  };
  visit(message?.payload);
  const directText = message?.text || message?.textPlain || message?.body?.text || '';
  const directHtml = message?.html || message?.textAsHtml || message?.body?.html || '';
  const text = normalizeText(decodeQuotedPrintable([directText, ...plain].filter(Boolean).join('\n\n')));
  if (text) return text;
  return normalizeText(decodeHtml(decodeQuotedPrintable([directHtml, ...html, message?.snippet].filter(Boolean).join('\n\n'))));
}

function isSystemSender(email) {
  const clean = String(email || '').toLowerCase();
  return !clean || /(^|[._-])(no-?reply|noreply|do-?not-?reply)([._-]|@)/.test(clean) || /mailer-daemon|notification|notifications|automated|shopify|forms?/.test(clean);
}

function isAutomatedOrderSummaryMessage(message) {
  if (!message || message.role !== 'support') return false;
  const text = normalizeText([message.subject, message.text, message.snippet].filter(Boolean).join('\n\n')).toLowerCase();
  return [
    /\bconfirmation de commande\b/,
    /\brésumé de commande\b/,
    /\bresume de commande\b/,
    /r.sum. de commande/,
    /\bnuméro de suivi\b/,
    /\bnumero de suivi\b/,
    /\btracking\b/,
    /\bsuivre votre colis\b/,
    /\badresse de livraison\b/,
    /\bmerci pour votre achat\b/,
  ].some((pattern) => pattern.test(text));
}

function extractOrderName(text) {
  const sourceText = String(text || '');
  const patterns = [
    /(?:commande|order|cmd|numero de commande|numéro de commande|n\s*de commande|n°\s*de commande)\s*[:#-]?\s*#?([0-9][A-Z0-9-]{2,29})\b/i,
    /#\s*([0-9]{3,12}[A-Z0-9-]*)\b/i,
  ];
  for (const pattern of patterns) {
    const match = sourceText.match(pattern);
    if (!match) continue;
    const candidate = String(match[1] || '').replace(/^#/, '').trim();
    if (/^[0-9][A-Z0-9-]{2,29}$/i.test(candidate)) return '#' + candidate;
  }
  return '';
}


function normalizeForMatch(value) {
  return String(value || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase();
}

function isQuotedThreadBoundary(line) {
  const clean = normalizeForMatch(line).trim();
  if (!clean) return false;
  return [
    /^>+/,
    /^[-_ ]{2,}\s*(message d origine|original message|forwarded message|message transfere)/,
    /^le .+ a .*crit\s*:/,
    /^on .+ wrote\s*:/,
    /^(de|from|envoye|sent|a|to|objet|subject)\s*:/,
    /^date\s*:/,
    /^expediteur\s*:/
  ].some((pattern) => pattern.test(clean));
}

function isOrderRecapBoundary(line) {
  const clean = normalizeForMatch(line).trim();
  if (!clean) return false;
  return [
    /\bresume de commande\b/,
    /\brecapitulatif de commande\b/,
    /\bconfirmation de commande\b/,
    /\bdetails de la commande\b/,
    /\barticles commandes\b/,
    /\badresse de livraison\b/,
    /\badresse de facturation\b/,
    /\bmode de livraison\b/,
    /\bnumero de suivi\b/,
    /\bnum[e?]ro de suivi\b/,
    /\bsuivre votre colis\b/,
    /\bvoir votre commande\b/,
    /\bmerci pour votre achat\b/,
    /\btotal\s*:/,
    /\bsous[- ]?total\s*:/
  ].some((pattern) => pattern.test(clean));
}

function extractLatestCustomerMessage(text) {
  const normalized = normalizeText(text);
  if (!normalized) return '';

  const lines = normalized.split('\n');
  const kept = [];
  for (const rawLine of lines) {
    const line = rawLine.trim();
    if (!line && kept.length === 0) continue;
    if (isQuotedThreadBoundary(line) && kept.some((value) => value.trim())) break;
    if (isOrderRecapBoundary(line) && kept.some((value) => value.trim())) break;
    if (/^>+/.test(line)) continue;
    kept.push(rawLine);
  }

  let latest = normalizeText(kept.join('\n'));
  latest = latest
    .replace(/\n{2,}\s*(cordialement|bien cordialement|bien a vous|bonne journee)[\s\S]*$/i, (match) => match.length > 500 ? '' : match)
    .trim();

  if (!latest || latest.length < 12) return normalized;
  return latest;
}

const currentHeaderMap = buildHeaderMap(source);
const currentFromRaw = source.from || getHeader(currentHeaderMap, 'from') || source.From || '';
const currentReplyToRaw = source.replyTo || getHeader(currentHeaderMap, 'reply-to') || '';
const currentFromEmail = extractEmailFromAny(currentFromRaw);
const currentReplyToEmail = extractEmailFromAny(currentReplyToRaw);
const subject = source.subject || getHeader(currentHeaderMap, 'subject') || source.Subject || 'Demande client';
const currentMessageId = String(source.id || source.messageId || source.message?.id || '').trim();
const currentThreadId = String(source.threadId || source.message?.threadId || source.payload?.threadId || threadEnvelope.id || '').trim();

const inboxAddresses = unique([
  ...((currentHeaderMap['delivered-to'] || []).map(extractEmail)),
  ...((currentHeaderMap['x-original-to'] || []).map(extractEmail)),
  ...((currentHeaderMap['envelope-to'] || []).map(extractEmail)),
  ...((currentHeaderMap.to || []).map(extractEmail)),
  extractEmailFromAny(source.to),
]).filter(Boolean);

let currentText = payloadToText(source);
const rawMessages = Array.isArray(threadEnvelope.messages) ? threadEnvelope.messages : [];
const currentThreadMessage = rawMessages.find((message) => String(message?.id || message?.messageId || '') === currentMessageId) || null;
if (!currentText && currentThreadMessage) currentText = payloadToText(currentThreadMessage);
if (!currentText && source.snippet) currentText = normalizeText(source.snippet);

const rawCurrentText = currentText;
const latestCustomerMessage = extractLatestCustomerMessage(currentText);
const customerMessageForAi = latestCustomerMessage || currentText;
const latestCustomerMessageWasTrimmed = Boolean(latestCustomerMessage && normalizeText(latestCustomerMessage) !== normalizeText(currentText));

const currentTextEmails = extractEmails(currentText);
const formContextLikely = isSystemSender(currentFromEmail) || /contact form|formulaire|form submission|nouveau message|online store|shopify|message depuis/i.test(currentText + '\n' + subject);
const formEmailCandidates = currentTextEmails.filter((email) => email && !isSystemSender(email) && !inboxAddresses.includes(email));

const headerCandidates = unique([
  currentReplyToEmail,
  currentFromEmail,
  extractEmailFromAny(source.sender),
  extractEmailFromAny(source.returnPath),
]).filter((email) => email && !isSystemSender(email) && !inboxAddresses.includes(email));

let replyToResolved = '';
let replyToSource = 'blocked';
let replyAddressConfidence = 'none';
let replyAddressAmbiguous = false;
let replyRoutingReason = 'no_safe_reply_target';

if (formContextLikely && formEmailCandidates.length === 1) {
  replyToResolved = formEmailCandidates[0];
  replyToSource = 'contact_form_body';
  replyAddressConfidence = 'high';
  replyRoutingReason = 'single_email_inside_contact_form';
} else if (formContextLikely && formEmailCandidates.length > 1) {
  replyToResolved = formEmailCandidates[0];
  replyToSource = 'contact_form_body';
  replyAddressConfidence = 'medium';
  replyAddressAmbiguous = true;
  replyRoutingReason = 'multiple_emails_inside_contact_form';
} else if (headerCandidates.length === 1) {
  replyToResolved = headerCandidates[0];
  replyToSource = 'header';
  replyAddressConfidence = 'high';
  replyRoutingReason = 'single_non_system_header';
} else if (headerCandidates.length > 1) {
  replyToResolved = headerCandidates[0];
  replyToSource = 'header';
  replyAddressConfidence = 'medium';
  replyAddressAmbiguous = true;
  replyRoutingReason = 'multiple_non_system_headers';
} else if (formEmailCandidates.length) {
  replyToResolved = formEmailCandidates[0];
  replyToSource = 'body_email';
  replyAddressConfidence = 'medium';
  replyRoutingReason = 'fallback_email_inside_body';
}

const replyConflictWithInbox = replyToResolved ? inboxAddresses.includes(replyToResolved) : false;
if (replyConflictWithInbox) {
  replyToResolved = '';
  replyToSource = 'blocked';
  replyAddressConfidence = 'none';
  replyRoutingReason = 'reply_target_is_internal';
}

const structuredMessages = rawMessages
  .map((message, index) => {
    const map = buildHeaderMap(message);
    const from = getHeader(map, 'from') || message.from || '';
    const to = getHeader(map, 'to') || message.to || '';
    const fromEmail = extractEmailFromAny(from);
    const role = fromEmail && !inboxAddresses.includes(fromEmail) && !isSystemSender(fromEmail) ? 'client' : 'support';
    return {
      id: String(message?.id || message?.messageId || 'msg-' + index),
      role,
      from,
      to,
      fromEmail,
      subject: String(getHeader(map, 'subject') || message?.subject || ''),
      internalDate: Number(message?.internalDate || Date.parse(getHeader(map, 'date')) || index),
      text: payloadToText(message),
      snippet: normalizeText(message?.snippet || ''),
    };
  })
  .filter((message) => message.text || message.snippet || message.subject)
  .sort((a, b) => a.internalDate - b.internalDate);

const previousThreadMessages = structuredMessages.filter((message) => message.id !== currentMessageId);
const usableThreadMessages = previousThreadMessages.filter((message) => !isAutomatedOrderSummaryMessage(message));
const recentThreadMessages = usableThreadMessages.slice(-8);
const threadHistoryText = recentThreadMessages
  .map((message) => '[' + message.role.toUpperCase() + '] ' + normalizeText(message.text || message.snippet).slice(0, 1200))
  .filter(Boolean)
  .join('\n\n');

const supportHistoryText = recentThreadMessages.filter((message) => message.role === 'support').map((message) => normalizeText(message.text || message.snippet)).join('\n\n');
const clientHistoryText = recentThreadMessages.filter((message) => message.role === 'client').map((message) => normalizeText(message.text || message.snippet)).join('\n\n');
const recentClientParticipants = unique(recentThreadMessages.filter((message) => message.role === 'client').map((message) => message.fromEmail)).filter(Boolean);

const threadSignals = {
  hasPriorSupportReply: /\bcordialement\b|\bnous restons disponibles\b/i.test(supportHistoryText),
  priorAskedReturnReason: /\b(raison de votre retour|préciser la raison|preciser la raison)\b/i.test(supportHistoryText),
  priorAskedForPhoto: /\b(photo|photos|image|emballage)\b/i.test(supportHistoryText),
  priorSizeExchangeProposal: /\b(taille différente|taille differente|échange|echange)\b/i.test(supportHistoryText),
  clientAlreadyAskedRefund: /\b(rembours|refund|argent)\b/i.test(clientHistoryText),
};

const customerFirstName = (() => {
  const name = extractNameFromAny(currentFromRaw).replace(/\s+/g, ' ').trim();
  if (!name || name.includes('@')) return '';
  const first = name.split(' ')[0].replace(/[^A-Za-zÀ-ÖØ-öø-ÿ'-]/g, '');
  return first.length >= 2 ? first : '';
})();

const customerEmail = replyToResolved || currentReplyToEmail || (!isSystemSender(currentFromEmail) ? currentFromEmail : '') || formEmailCandidates[0] || '';
const orderName = extractOrderName(subject + '\n' + currentText);

return [
  {
    json: {
      gmailMessageId: currentMessageId,
      threadId: currentThreadId,
      originalThreadId: currentThreadId,
      originalMessageId: currentMessageId,
      fromRaw: currentFromRaw,
      originalFromEmail: currentFromEmail,
      originalReplyTarget: replyToResolved,
      replyToResolved,
      replyToSource,
      replyAddressConfidence,
      replyAddressAmbiguous,
      replyRoutingReason,
      replyConflictWithInbox,
      inboxAddresses,
      recentClientParticipants,
      contactFormLikely: formContextLikely,
      customerEmail,
      customerFirstName,
      originalSubject: subject,
      customerMessage: customerMessageForAi,
      latestCustomerMessage: customerMessageForAi,
      rawCustomerMessage: rawCurrentText,
      latestCustomerMessageWasTrimmed,
      threadHistoryText,
      threadSignals,
      orderName,
      receivedAt: source.date || source.internalDate || new Date().toISOString(),
      createAsReply: Boolean(currentThreadId)
    }
  }
];

const ctx = $('Prepare Shopify Query').first().json;
const shopifyRaw = $input.first().json;
const order = shopifyRaw?.data?.orders?.nodes?.[0] || null;
const fulfillments = Array.isArray(order?.fulfillments) ? order.fulfillments : [];
let trackingNumber = '';
let trackingCompany = '';
let trackingUrl = '';
let estimatedDeliveryAt = '';

for (const fulfillment of fulfillments) {
  if (!estimatedDeliveryAt && fulfillment.estimatedDeliveryAt) estimatedDeliveryAt = fulfillment.estimatedDeliveryAt;
  const infos = Array.isArray(fulfillment.trackingInfo) ? fulfillment.trackingInfo : [];
  for (const info of infos) {
    if (info?.number) {
      trackingNumber = info.number;
      trackingCompany = info.company || '';
      trackingUrl = info.url || '';
      break;
    }
  }
  if (trackingNumber) break;
}

return [
  {
    json: {
      ...ctx,
      shopifyRaw,
      orderFound: Boolean(order),
      order,
      orderDisplayName: order?.name || ctx.orderName || '',
      fulfillmentStatus: order?.displayFulfillmentStatus || '',
      trackingNumber,
      trackingCompany,
      trackingUrl,
      estimatedDeliveryAt,
      track17RegisterBody: trackingNumber ? [{ number: trackingNumber, carrier: null, tag: order?.name || ctx.orderName || '' }] : [],
      track17QueryBody: trackingNumber ? [{ number: trackingNumber, carrier: null }] : []
    }
  }
];

const ctx = $('Prepare AI Understanding').first().json;
const raw = $input.first().json;

function textFrom(value) {
  if (typeof value === 'string') return value;
  if (value == null) return '';
  if (typeof value === 'object') return JSON.stringify(value);
  return String(value);
}

function extractOutputText(response) {
  const directCandidates = [
    response?.output_text,
    typeof response?.output === 'string' ? response.output : '',
    response?.text,
    response?.message?.content,
    response?.choices?.[0]?.message?.content,
    response?.data?.[0]?.content?.[0]?.text,
    response?.content,
    response?.json,
    response?.result,
    response?.answer
  ];
  for (const candidate of directCandidates) {
    const text = textFrom(candidate).trim();
    if (text) return text;
  }

  const output = Array.isArray(response?.output) ? response.output : [];
  for (const item of output) {
    const content = Array.isArray(item?.content) ? item.content : [];
    for (const part of content) {
      const text = textFrom(part?.text || part?.output_text || part?.content).trim();
      if (text) return text;
    }
  }

  if (Array.isArray(response)) {
    for (const item of response) {
      const text = extractOutputText(item);
      if (text) return text;
    }
  }

  return '';
}

function parseJsonSafe(rawText) {
  const clean = String(rawText || '')
    .trim()
    .replace(/^\x60\x60\x60(?:json)?\s*/i, '')
    .replace(/\x60\x60\x60$/i, '')
    .trim();
  if (!clean) return null;
  try {
    return JSON.parse(clean);
  } catch (firstError) {
    const match = clean.match(/\{[\s\S]*\}/);
    if (!match) throw firstError;
    return JSON.parse(match[0]);
  }
}

function fallbackUnderstanding() {
  return {
    intent: 'other',
    language: 'fr',
    sentiment: 'neutral',
    product_id: 'default_product',
    product_name: '',
    order_name: ctx.orderName || '',
    customer_email_in_message: '',
    summary_fr: 'Analyse IA indisponible ou non parseable.',
    requested_action_fr: 'Verification manuelle necessaire.',
    needs_order_lookup: Boolean(ctx.customerEmail || ctx.orderName),
    needs_human_review: true,
    confidence: 0,
    recommended_template_id: 'generic_clarification',
    should_create_draft: true,
    skip_draft_reason: ''
  };
}

function normalize(value) {
  return String(value || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
}

function unique(values) {
  return [...new Set(values.map((value) => String(value || '').trim()).filter(Boolean))];
}

function hasAny(blob, patterns) {
  return patterns.some((pattern) => pattern.test(blob));
}

let aiUnderstanding = fallbackUnderstanding();
const aiUnderstandingText = extractOutputText(raw);

try {
  const parsed = parseJsonSafe(aiUnderstandingText);
  if (parsed) aiUnderstanding = parsed;
} catch (error) {
  aiUnderstanding.parse_error = error.message;
}

const products = Array.isArray(ctx.products) ? ctx.products : [];
const templates = ctx.supportTemplates || {};
const defaultProduct = products.find((product) => product.id === 'default_product') || null;
const requestedProductId = String(aiUnderstanding.product_id || '').trim();
const latestCustomerText = String(ctx.latestCustomerMessage || ctx.customerMessage || '').trim();
const latestCustomerBlob = normalize(latestCustomerText);
const subjectBlob = normalize(ctx.originalSubject || '');
const latestHasBody = latestCustomerBlob.length >= 12;
const messageBlob = normalize([
  latestCustomerText,
  !latestHasBody ? ctx.originalSubject || '' : '',
  aiUnderstanding.product_name || '',
  requestedProductId
].join(' '));

let selectedProduct =
  products.find((product) => product.id === requestedProductId && requestedProductId !== 'default_product') ||
  products.find((product) => product.id !== 'default_product' && (product.aliases || []).some((alias) => messageBlob.includes(normalize(alias)))) ||
  defaultProduct ||
  null;

const nonClientIntentSet = new Set(['partnership_request', 'marketing_or_sales', 'automated_notification', 'not_customer_request']);
const nonClientPatternBlob = normalize([
  ctx.fromRaw || '',
  ctx.originalFromEmail || '',
  ctx.originalSubject || '',
  latestCustomerText
].join(' '));
const deterministicNonClientPatterns = [
  /\b(partenariat|collaboration|influenceur|influenceuse|affiliation|sponsoring|sponsorise|ambassadeur|ambassadrice)\b/,
  /\b(agence\s+(marketing|seo)|seo|backlink|guest\s*post|article sponsorise|publicite|prospection|lead generation)\b/,
  /\b(newsletter|unsubscribe|desabonner|desinscription|mailing list)\b/,
  /\b(no-?reply|noreply|do-?not-?reply|mailer-daemon|notification automatique|automated notification|message automatique)\b/,
  /\b(echec de remise|non livraison|non delivrance|adresse inconnue|boite mail pleine|mail delivery|delivery status notification)\b/,
  /\b(enquete bancaire|litige bancaire|chargeback|contestation bancaire|a ouvert une enquete)\b/,
  /\b(security alert|alerte securite|code de verification|verification code|mot de passe|password reset)\b/,
  /\b(invoice|facture automatique|recu automatique|receipt|statement)\b/
];
const customerComplaintSignals = hasAny(latestCustomerBlob, [
  /\b(commande|colis|produit|article|genouillere|genouilleres|taille|rembours|retour|echange|recu|recue|livraison|guide)\b/,
  /#\s*[0-9]{3,12}\b/,
  /\b(arnaque|decu|decue|pas conforme|rien a voir|publicite facebook)\b/
]);
