function hasMeaningful17TrackData(response) {
  if (!response || typeof response !== 'object') return false;
  if (response.error || response.errorMessage || response.message?.error) return false;
  const serialized = JSON.stringify(response).toLowerCase();
  if (/unauthorized|forbidden|invalid token|invalid api|missing token|api key|quota|rate limit/.test(serialized)) return false;
  return Boolean(
    response.data ||
    response.track_info ||
    response.trackInfo ||
    response.accepted ||
    response.rejected ||
    response.event ||
    response.events
  );
}

