function getSentMailLearningExamples() {
  let memory = [];
  try {
    const staticData = $getWorkflowStaticData('global');
    memory = Array.isArray(staticData.lineaParisSentMailLearning) ? staticData.lineaParisSentMailLearning : [];
  } catch {
    memory = [];
  }
  const wantedTemplateIds = new Set(templatesToUse.map((template) => String(template?.id || '').trim()).filter(Boolean));
  const wantedFamilies = new Set(templatesToUse.map((template) => String(template?.family || '').trim()).filter(Boolean));
  const scored = memory
    .filter((item) => item && Array.isArray(item.paragraphs) && item.paragraphs.length)
    .map((item) => {
      const templateMatch = wantedTemplateIds.has(String(item.templateId || '').trim()) ? 2 : 0;
      const familyMatch = wantedFamilies.has(String(item.family || '').trim()) ? 1 : 0;
      return { item, score: templateMatch + familyMatch };
    })
    .filter((entry) => entry.score > 0)
    .sort((a, b) => {
      if (b.score !== a.score) return b.score - a.score;
      return Date.parse(b.item.sentAt || 0) - Date.parse(a.item.sentAt || 0);
    })
    .slice(0, 6)
    .map((entry) => ({
      templateId: entry.item.templateId || '',
      family: entry.item.family || '',
      subjectShape: entry.item.subjectShape || '',
      paragraphs: entry.item.paragraphs.slice(0, 5),
      source: entry.item.source || 'gmail_sent_after_manual_review'
    }));
  return scored;
}

