function templateCoreForPrompt(body) {
  return String(body || '')
    .replace(/\r\n/g, '\n')
    .replace(/^Bonjour[\s,!.]*\n+/i, '')
    .replace(/^Merci pour votre message\.?\n+/i, '')
    .replace(/\n*Nous restons disponibles[\s\S]*$/i, '')
    .replace(/\n*Cordialement,[\s\S]*$/i, '')
    .trim();
}

function templateForPrompt(template) {
  if (!template) return null;
  return {
    id: template.id,
    family: template.family,
    description: template.description,
    source: template.source,
    exampleCore: templateCoreForPrompt(template.body),
    requiresAttachment: Boolean(template.requiresAttachment),
    needsHumanReview: Boolean(template.needsHumanReview),
    safeUsageNotes: template.safeUsageNotes || []
  };
}

