function stripTemplateChrome(body) {
  let text = String(body || '').replace(/\r\n/g, '\n').trim();
  text = text.replace(/^Bonjour[\s,!.]*\n+/i, '');
  text = text.replace(/^Merci pour votre message\.?\n+/i, '');
  text = text.replace(/\n*Nous restons disponibles[\s\S]*$/i, '');
  text = text.replace(/\n*Cordialement,[\s\S]*$/i, '');
  return text.trim();
}

function combinedTemplateBody(signature) {
  const templates = selectedTemplates.length ? selectedTemplates : [selectedTemplate].filter(Boolean);
  const paragraphs = [];
  for (const template of templates) {
    const core = stripTemplateChrome(template?.body || '');
    if (!core) continue;
    for (const paragraph of core.split(/\n{2,}/).map((part) => part.trim()).filter(Boolean)) {
      const normalizedParagraph = normalize(paragraph);
      if (!paragraphs.some((existing) => normalize(existing) === normalizedParagraph)) paragraphs.push(paragraph);
    }
  }

  if (!paragraphs.length) {
    paragraphs.push('Nous avons bien pris en compte votre demande.');
    paragraphs.push('Nous avons fait le n\u00e9cessaire de notre c\u00f4t\u00e9.');
  }

  return [
    'Bonjour,',
    '',
    'Merci pour votre message.',
    '',
    paragraphs.join('\n\n'),
    '',
    'Nous restons disponibles pour toute question.',
    '',
    'Cordialement,',
    signature
  ].join('\n');
}

function fallbackDraft(reason = 'reponse_ia_indisponible_ou_non_parseable') {
  const signature = data.supportSignature || data.brand?.signature || 'L equipe support';
  const subject = data.originalSubject || 'Votre demande';
  const body = combinedTemplateBody(signature);
  return {
    reply_subject: /^re:/i.test(subject) ? subject : 'Re: ' + subject,
    reply_body: body,
    internal_summary: finalTemplateIds.length
      ? 'Brouillon de secours base sur les templates ' + finalTemplateIds.join(', ') + ' car la reponse IA etait indisponible, incomplete ou non parseable.'
      : 'Brouillon de secours utilise car la reponse IA etait indisponible ou non parseable.',
    needs_human_review: true,
    confidence: 0,
    template_id_used: finalTemplateIds.join('+') || 'fallback_generic',
    fallback_reason: reason
  };
}

function hasVagueVerification(body) {
  const normalizedBody = normalize(body);
  return [
    'allons verifier',
    'vais verifier',
    'va verifier',
    'verifier votre dossier',
    'verification de votre dossier',
    'reponse precise au plus vite'
  ].some((phrase) => normalizedBody.includes(phrase));
}

function templateAppearsCovered(templateId, normalizedBody) {
  const requirements = {
    guide: ['guide', 'piece jointe'],
    taille_confirmee: ['taille'],
    taille_incomplete: ['taille'],
    retour_taille: ['taille'],
    genouillere_manquante: ['genouillere', 'manquante', 'necessaire'],
    produit_abime: ['demande', 'necessaire'],
    remboursement: ['rembours'],
    livraison: ['commande'],
    livraison_affichage_livre: ['affichage', 'pas encore ete livre'],
    annulation: ['annulation'],
    retour_details: ['retour'],
    offre: ['offre'],
    logo: ['logo'],
    product_info_generic: ['genouillere']
  };
  const required = requirements[templateId] || [];
  return required.every((word) => normalizedBody.includes(word));
}

function mustUseTemplateFallback(draft) {
  const body = String(draft?.reply_body || '').trim();
  if (!body) return true;
  const normalizedBody = normalize(body);
  if (finalTemplateIds.includes('guide')) {
    const guideOk = normalizedBody.includes('guide') &&
      (normalizedBody.includes('dematerialise') || normalizedBody.includes('numerique')) &&
      normalizedBody.includes('piece jointe');
    if (!guideOk) return true;
  }
  // Do not force exact wording for delivery-display cases; the writer can phrase it naturally.
  if (finalTemplateIds.includes('genouillere_manquante')) {
    const asksUnneededInfo = normalizedBody.includes('photo') || normalizedBody.includes('numero de commande') || normalizedBody.includes('transmettre votre numero') || normalizedBody.includes('informations de suivi') || normalizedBody.includes('numero de suivi') || normalizedBody.includes('offre achetee') || normalizedBody.includes('offerte') || normalizedBody.includes('allons verifier') || normalizedBody.includes('verifier votre dossier');
    const missingItemCovered = /(genouillere|article|produit)/.test(normalizedBody) && /(manqu|renvoi|renvoyer|necessaire|pris en compte)/.test(normalizedBody);
    if (asksUnneededInfo || !missingItemCovered) return true;
  }
  if (finalTemplateIds.includes('produit_abime')) {
    const asksUnneededInfo = normalizedBody.includes('photo') || normalizedBody.includes('numero de commande') || normalizedBody.includes('transmettre votre numero') || normalizedBody.includes('allons verifier') || normalizedBody.includes('verifier votre dossier');
    if (asksUnneededInfo) return true;
  }
  if (finalTemplateIds.includes('retour_details')) {
    const asksUnneededInfo = normalizedBody.includes('photo') || normalizedBody.includes('numero de commande') || normalizedBody.includes('transmettre votre numero') || normalizedBody.includes('allons verifier') || normalizedBody.includes('verifier votre dossier');
    if (asksUnneededInfo) return true;
  }
  if (finalTemplateIds.includes('taille_incomplete')) {
    const asksUnneededInfo = normalizedBody.includes('numero de commande') || normalizedBody.includes('transmettre votre numero') || normalizedBody.includes('photo');
    if (asksUnneededInfo) return true;
  }
  // Multi-request drafts should not be replaced by a stitched template just because wording differs.
  if (primaryTemplateId && !['generic_clarification', 'empty_body'].includes(primaryTemplateId) && hasVagueVerification(body)) return true;
  return false;
}

