function extractEmail(value) {
  const raw = String(value || '').trim();
  if (!raw) return '';
  const angle = raw.match(/<([^>]+)>/);
  if (angle && angle[1]) return angle[1].trim().toLowerCase();
  const direct = raw.match(/[A-Z0-9._%+-]+@[.A-Z0-9-]+[.][A-Z]{2,}/i);
  return direct ? direct[0].toLowerCase() : '';
}

function extractEmails(value) {
  if (!value) return [];
  if (Array.isArray(value)) return value.flatMap(extractEmails);
  if (typeof value === 'object') {
    return [
      ...extractEmails(value.address),
      ...extractEmails(value.email),
      ...extractEmails(value.text),
      ...extractEmails(value.value),
      ...extractEmails(value.from),
      ...extractEmails(value.replyTo)
    ];
  }
  return String(value).match(/[A-Z0-9._%+-]+@[.A-Z0-9-]+[.][A-Z]{2,}/ig)?.map((email) => email.toLowerCase()) || [];
}

function unique(values) {
  return [...new Set(values.map((value) => String(value || '').trim().toLowerCase()).filter(Boolean))];
}

function normalize(value) {
  return String(value || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase();
}

function isSystemEmail(email) {
  const clean = String(email || '').toLowerCase();
  return !clean || /(^|[._-])(no-?reply|noreply|do-?not-?reply)([._-]|@)/.test(clean) || /mailer-daemon|notification|notifications|automated|shopify|forms?/.test(clean);
}

const inboxAddresses = unique(Array.isArray(source.inboxAddresses) ? source.inboxAddresses : []);
const explicitCandidates = unique([
  extractEmail(source.replyToResolved),
  extractEmail(source.originalReplyTarget),
  extractEmail(source.draftTo),
  extractEmail(source.customerEmail),
  extractEmail(source.aiUnderstanding?.customer_email_in_message),
  ...(Array.isArray(source.recentClientParticipants) ? source.recentClientParticipants.map(extractEmail) : []),
  extractEmail(source.originalFromEmail),
  extractEmail(source.fromRaw)
]);
const bodyCandidates = unique([
  ...extractEmails(source.customerMessage),
  ...extractEmails(source.threadHistoryText),
  ...extractEmails(source.aiUnderstandingText),
  ...extractEmails(source.aiDraftText)
]);
const allCandidates = unique([...explicitCandidates, ...bodyCandidates]);
const rejectedCandidates = [];
let sendTo = '';
let sendToSource = '';

// Phase 1: prefer a clean client email.
for (const candidate of allCandidates) {
  if (!candidate) continue;
  if (inboxAddresses.includes(candidate)) {
    rejectedCandidates.push({ email: candidate, reason: 'internal_inbox_address_preferred_phase' });
    continue;
  }
  if (isSystemEmail(candidate)) {
    rejectedCandidates.push({ email: candidate, reason: 'system_or_no_reply_preferred_phase' });
    continue;
