    if (!key) continue;
    map[key] = map[key] || [];
    map[key].push(String(header?.value || ''));
  }
  return map;
}

const getHeader = (map, name) => (map[String(name || '').toLowerCase()] || [])[0] || '';

function decodeBase64Url(input) {
  const raw = String(input || '').trim();
  if (!raw) return '';
  const normalized = raw.replace(/-/g, '+').replace(/_/g, '/');
  const padded = normalized + '='.repeat((4 - (normalized.length % 4)) % 4);
  try { return Buffer.from(padded, 'base64').toString('utf8'); } catch { return ''; }
}

function decodeHtml(input) {
  return String(input || '')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;|&apos;/gi, "'")
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/p>/gi, '\n')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<[^>]+>/g, ' ');
}

function payloadToText(message) {
  const plain = [];
  const html = [];
  const visit = (part) => {
    if (!part) return;
    const mime = String(part.mimeType || '').toLowerCase();
    const data = part.body?.data ? decodeBase64Url(part.body.data) : '';
    if (data && mime.includes('text/plain')) plain.push(data);
    else if (data && mime.includes('text/html')) html.push(decodeHtml(data));
    if (Array.isArray(part.parts)) part.parts.forEach(visit);
  };
  visit(message?.payload);
  const directText = message?.text || message?.textPlain || message?.body?.text || '';
  const directHtml = message?.html || message?.textAsHtml || message?.body?.html || '';
  const text = normalizeText([directText, ...plain].filter(Boolean).join('\n\n'));
  if (text) return text;
  return normalizeText(decodeHtml([directHtml, ...html, message?.snippet].filter(Boolean).join('\n\n')));
}

function stripQuotedHistory(text) {
  const lines = normalizeText(text).split('\n');
  const kept = [];
  for (const rawLine of lines) {
    const line = rawLine.trim();
    const clean = normalize(line);
    if (/^>+/.test(line)) continue;
    if (kept.some((value) => value.trim()) && (
      /^le .+ a .*crit\s*:/.test(clean) ||
      /^on .+ wrote\s*:/.test(clean) ||
      /message d origine|original message|forwarded message/.test(clean) ||
      /envoye depuis yahoo|sent from my iphone/.test(clean)
    )) break;
    kept.push(rawLine);
  }
  return normalizeText(kept.join('\n'));
}

function stripChrome(body) {
  let text = stripQuotedHistory(body);
  text = text.replace(/^Bonjour[\s,!.]*\n+/i, '');
  text = text.replace(/^Merci pour votre message\.?\n+/i, '');
  text = text.replace(/\n*Nous restons disponibles[\s\S]*$/i, '');
  text = text.replace(/\n*Cordialement,[\s\S]*$/i, '');
  return normalizeText(text);
}

function classifySentReply(subject, body) {
  const blob = normalize(subject + '\n' + body);
  const checks = [
    ['guide', /\b(guide|livre|pdf|piece jointe|dematerialise|genou sans douleur)\b/],
    ['genouillere_manquante', /\b(genouillere|article|produit)\b.*\b(manquante|manquant|renvoyer|renvoi)\b|\bmanquante\b.*\bgenouillere\b/],
    ['livraison_affichage_livre', /\b(probleme d affichage|affichee livree|indique livree|pas encore ete livre)\b/],
    ['livraison', /\b(acheminement|retard|livraison|transporteur|colis|suivi|courant de la semaine|debut de semaine prochaine|fin de semaine prochaine)\b/],
    ['remboursement', /\b(remboursement|rembourser|confirmation de remboursement)\b/],
    ['retour_taille', /\b(taille|taille au dessus|taille superieure|echange|retour)\b/],
    ['adresse', /\b(adresse|modification d adresse|nouvelle adresse)\b/],
    ['annulation', /\b(annulation|annuler)\b/],
    ['produit_abime', /\b(abime|defectueux|casse|endommage|defaut)\b/],
    ['conseil_taille', /\b(tour de genou|cm|quelle taille|taille choisir|glisse|roule|serre)\b/],
    ['livraison_internationale', /\b(luxembourg|belgique|suisse|royaume uni|international|pays)\b/],
    ['commande_confirmation', /\b(commande validee|commande a bien ete validee|email de confirmation|courriers indesirables|paiement)\b/],
    ['logo', /\b(logo|marquage|etiquette|design discret)\b/]
  ];
  const found = checks.find(([, pattern]) => pattern.test(blob));
  return found ? found[0] : 'autre';
}

const headerMap = buildHeaderMap(source);
const subject = source.subject || getHeader(headerMap, 'subject') || '';
const fromEmail = extractEmail(source.from || getHeader(headerMap, 'from'));
const toEmail = extractEmail(source.to || getHeader(headerMap, 'to'));
const messageId = String(source.id || source.messageId || '').trim();
const threadId = String(source.threadId || source.message?.threadId || '').trim();
const sentAt = source.date || getHeader(headerMap, 'date') || new Date().toISOString();
const fullBody = payloadToText(source);
const finalBody = stripQuotedHistory(fullBody);
const coreBody = stripChrome(finalBody);
const brandLikely = /linea\s*paris|lin[?e]a\s*paris/i.test(subject + '\n' + finalBody) || /l[?']?equipe\s+linea\s+paris|l[?']??quipe\s+lin?a\s+paris/i.test(finalBody);

if (!brandLikely) {
  return [{ json: { sentAuditStatus: 'ignored_non_linea_support_sent_mail', messageId, subject, toEmail, sentAt } }];
}

const paragraphs = coreBody
  .split(/\n{2,}/)
  .map((part) => normalizeText(part))
  .filter((part) => part && part.length >= 12)
  .filter((part) => !/^bonjour/i.test(part) && !/^merci pour votre message/i.test(part))
  .slice(0, 8)
  .map((part) => part.slice(0, 600));

const templateId = classifySentReply(subject, finalBody);
const learning = {
  id: messageId || (threadId + ':' + Date.parse(sentAt || new Date().toISOString())),
  threadId,
  templateId,
  family: ['livraison', 'livraison_affichage_livre'].includes(templateId) ? 'livraison' : (['remboursement', 'retour_taille', 'genouillere_manquante', 'produit_abime', 'annulation'].includes(templateId) ? 'remboursement' : 'autre'),
  sentAt,
  subjectShape: subject.replace(/^(re|fw|fwd|tr)\s*:\s*/i, '').replace(/#\d+/g, '#COMMANDE').slice(0, 180),
  paragraphs,
  bodyPreview: finalBody.slice(0, 1200),
  source: 'gmail_sent_after_manual_review'
};

let memoryCount = 0;
try {
  const staticData = $getWorkflowStaticData('global');
  const key = 'lineaParisSentMailLearning';
  const existing = Array.isArray(staticData[key]) ? staticData[key] : [];
  const withoutDuplicate = existing.filter((item) => item && item.id !== learning.id);
  withoutDuplicate.push(learning);
  staticData[key] = withoutDuplicate.slice(-80);
  staticData.lineaParisSentMailLearningUpdatedAt = new Date().toISOString();
  memoryCount = staticData[key].length;
} catch (error) {
  return [{ json: { sentAuditStatus: 'memory_write_failed', messageId, subject, toEmail, sentAt, templateId, error: error.message, learning } }];
}

return [{
  json: {
    sentAuditStatus: 'recorded_for_future_drafts_only',
    messageId,
    threadId,
    subject,
    toEmail,
    fromEmail,
    sentAt,
    templateId,
    learnedParagraphCount: paragraphs.length,
    memoryCount,
    learningPreview: learning,
    note: 'Lecture seule: aucun email envoye, aucun brouillon cree. Ces exemples servent seulement a guider les prochains brouillons.'
  }
}];
